const cm = L2D._c2.model.internalModel.coreModel;
const m = cm._model;
const ids = [...m.parameters.ids];
const mins = [...m.parameters.minimumValues];
const maxs = [...m.parameters.maximumValues];

// 儲存原始值
const originals = ids.map(id => cm.getParameterValueById(id));

// 注入極限爆發隨機值（只挑選會影響身體、頭部與大動作的參數，避免小參數分流強度）
function glitchRandomize() {
  ids.forEach((id, i) => {
    // 聚焦於關鍵的動態參數，給予最大幅度的隨機值，其餘參數隨機放大
    if (id.includes('ANGLE') || id.includes('ROT') || id.includes('STRETCH') || id.includes('SHOLDER')) {
      // 隨機在極大值（max）與極小值（min）之間極端跳躍，創造極強烈的視覺拉扯
      const bias = Math.random() > 0.5 ? maxs[i] : mins[i];
      const jitter = (Math.random() - 0.5) * (maxs[i] - mins[i]) * 0.3; // 帶有一點中央抖動
      cm.setParameterValueById(id, Math.max(mins[i], Math.min(maxs[i], bias + jitter)));
    } else {
      // 一般參數全範圍亂數
      const v = mins[i] + Math.random() * (maxs[i] - mins[i]);
      cm.setParameterValueById(id, v);
    }
  });
}

// 還原
function restore() {
  ids.forEach((id, i) => cm.setParameterValueById(id, originals[i]));
  console.log('⚡ 【失控崩壞】動作結束，已還原基本姿勢');
}

// 高頻率觸發：每 16ms 換一次隨機極端姿勢（高爆發抽搐），持續 1.5 秒（約 90 次）後還原
let count = 0;
const totalTicks = 90; 
console.log('🔥 啟動：【失控崩壞】極速隨機抽搐...');

const timer = setInterval(() => {
  if (count >= totalTicks) { 
    clearInterval(timer); 
    restore(); 
    return; 
  }
  count++;
  glitchRandomize();
}, 16); // 16ms 逼近螢幕刷新率，強行在原生 Motion 空隙塞滿殘影



